// Wire the tunnel's inbound coordination control into the desktop wake path (#935).
// src-tauri/src/tunnel.rs decodes a phone's wake/approve frames and re-emits them as
// Tauri events; without a listener they fell on the floor. This hook routes them through
// the SAME actuation the local Coordinator inbox uses, so a paired phone can wake a parked
// worker or approve a paused gate. Mount once at the app root (runs on any screen).
//
// THE DECISION IS NOT HERE ANY MORE. Reading coord.log, folding it and deciding whether the named
// session may be resumed is `mobile_resume_plan`, in the process that owns the log and the sessions
// — `logs::wakes::plan_mobile_resume`. This hook still owns the ACTUATION, because relaunching a
// pane goes through the store's `wakePane`, which only the renderer has.

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { actuateWake, injectWake } from "@/shared/lib/fleet/coordinatorActuate";
import { log } from "@/shared/lib/core/log";

/** What a paired phone asked for. The backend narrows the wire token and refuses anything else. */
type CoordControlKind = "wake" | "approve";

/** One honoured request, as `mobile_resume_plan` returns it. */
interface MobileResume {
  session: string;
  /** The wake/resume prompt delivered to the session. */
  prompt: string;
  /** `fresh` relaunches the parked pane; `inject` delivers into the live, paused one. */
  via: "fresh" | "inject";
}

export function useTunnelCoordControl(): void {
  useEffect(() => {
    let cancelled = false;

    const handle = async (kind: CoordControlKind, session: string): Promise<void> => {
      // ONE call: the tail read, the fold and the decision all happen backend-side. The renderer
      // used to do the last two after a `logsTail` invoke, so a phone's request reached a decision
      // that existed only inside a live webview.
      const plan = await safeInvoke<MobileResume | null>("mobile_resume_plan", { kind, session }, null);
      if (cancelled) return;
      if (!plan) {
        // The phone named a session that isn't parked, or a verb the backend does not know — ignore
        // rather than wake blindly. (A backend that could not answer degrades the same way, which is
        // the safe direction for a verb that resumes an agent.)
        log.warn(`tunnel: ignoring mobile ${kind} for "${session}" — not a parked session`);
        return;
      }
      log.info(`tunnel: mobile ${kind} → ${plan.via} resume of "${plan.session}"`);
      if (plan.via === "fresh") {
        await actuateWake(plan.session, plan.prompt, useAppStore.getState().wakePane);
      } else {
        await injectWake(plan.session, plan.prompt);
      }
    };

    const subs = [
      listen<{ session: string }>("tunnel://coord-wake", (e) => void handle("wake", e.payload.session)),
      listen<{ session: string }>("tunnel://coord-approve", (e) => void handle("approve", e.payload.session)),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

