/**
 * @vitest-environment jsdom
 *
 * This file lives under `lib/`, which vitest's `node` project covers, but it genuinely needs a DOM.
 * A per-file docblock beats the project's environment, so the requirement is stated where a reader
 * meets it. See the `projects` split in vitest.config.ts for why the default is `node` here.
 *
 * THE DECISION IS NOT TESTED HERE ANY MORE. Which sessions may be resumed, and by which verb, is
 * `logs::wakes::plan_mobile_resume` and is asserted in Rust — this file covers the half that stayed:
 * subscribe to both events, ASK with the right arguments, and actuate the answer the right way.
 */
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, waitFor } from "@testing-library/react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";

vi.mock("@/shared/lib/fleet/coordinatorActuate", () => ({
  actuateWake: vi.fn().mockResolvedValue(true),
  injectWake: vi.fn().mockResolvedValue(true),
}));

import { actuateWake, injectWake } from "@/shared/lib/fleet/coordinatorActuate";
import { useTunnelCoordControl } from "@/features/tunnel/lib/useTunnelCoordControl";

const handlers: Record<string, (e: { payload: { session: string } }) => void> = {};

/** Make `mobile_resume_plan` answer with `plan`; every other command resolves null. */
function planIs(plan: unknown) {
  vi.mocked(invoke).mockImplementation((cmd: string) =>
    Promise.resolve(cmd === "mobile_resume_plan" ? plan : null),
  );
}

beforeEach(() => {
  vi.clearAllMocks();
  for (const k of Object.keys(handlers)) delete handlers[k];
  vi.mocked(listen).mockImplementation((name, cb) => {
    handlers[name] = cb as (e: { payload: { session: string } }) => void;
    return Promise.resolve(() => {});
  });
  planIs(null);
});

/** Mount and wait for both subscriptions to be live. */
async function mounted() {
  renderHook(() => useTunnelCoordControl());
  await waitFor(() => {
    expect(handlers["tunnel://coord-wake"]).toBeTypeOf("function");
    expect(handlers["tunnel://coord-approve"]).toBeTypeOf("function");
  });
}

describe("useTunnelCoordControl (#935)", () => {
  it("subscribes to both inbound coordination events", async () => {
    await mounted();
  });

  it("routes a mobile approve into an in-place resume of a paused gate", async () => {
    planIs({ session: "api", prompt: "you have been resumed", via: "inject" });
    await mounted();

    handlers["tunnel://coord-approve"]({ payload: { session: "api" } });

    await waitFor(() => expect(injectWake).toHaveBeenCalledWith("api", "you have been resumed"));
    expect(actuateWake).not.toHaveBeenCalled();
  });

  it("routes a mobile wake into a fresh relaunch of a ready dependency waiter", async () => {
    planIs({ session: "web", prompt: "your dependency has landed", via: "fresh" });
    await mounted();

    handlers["tunnel://coord-wake"]({ payload: { session: "web" } });

    await waitFor(() =>
      expect(actuateWake).toHaveBeenCalledWith("web", "your dependency has landed", expect.any(Function)),
    );
    expect(injectWake).not.toHaveBeenCalled();
  });

  /** The kind and the session must actually be SENT — a handler that asked for the wrong session, or
   *  sent no kind at all, would still route whatever the backend happened to answer with. */
  it("asks the backend with the verb and the session the phone named", async () => {
    planIs(null);
    await mounted();

    handlers["tunnel://coord-approve"]({ payload: { session: "api" } });
    await waitFor(() =>
      expect(invoke).toHaveBeenCalledWith("mobile_resume_plan", { kind: "approve", session: "api" }),
    );

    handlers["tunnel://coord-wake"]({ payload: { session: "web" } });
    await waitFor(() =>
      expect(invoke).toHaveBeenCalledWith("mobile_resume_plan", { kind: "wake", session: "web" }),
    );
  });

  it("ignores a request naming a session that isn't parked", async () => {
    planIs(null);
    await mounted();

    handlers["tunnel://coord-wake"]({ payload: { session: "ghost" } });

    // Give the async handler a chance to run, then assert nothing was actuated.
    await new Promise((r) => setTimeout(r, 0));
    expect(actuateWake).not.toHaveBeenCalled();
    expect(injectWake).not.toHaveBeenCalled();
  });

  /** A backend that cannot answer degrades to NO resume, never to a blind one — the same direction
   *  the old `readCoordState` null guard took, and the safe one for a verb that restarts an agent. */
  it("actuates nothing when the backend cannot answer", async () => {
    vi.mocked(invoke).mockRejectedValue(new Error("backend down"));
    await mounted();

    handlers["tunnel://coord-approve"]({ payload: { session: "api" } });

    await new Promise((r) => setTimeout(r, 0));
    expect(actuateWake).not.toHaveBeenCalled();
    expect(injectWake).not.toHaveBeenCalled();
  });
});
